import{_ as a,o,c as t,a3 as n}from"./chunks/framework.BKiFpLTg.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),r={name:"guide/faq.md"};function s(d,e,i,h,c,u){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="macos-says-blank-cannot-be-opened-or-is-damaged" tabindex="-1">macOS says Blank &quot;cannot be opened&quot; or &quot;is damaged&quot; <a class="header-anchor" href="#macos-says-blank-cannot-be-opened-or-is-damaged" aria-label="Permalink to &quot;macOS says Blank &quot;cannot be opened&quot; or &quot;is damaged&quot;&quot;">​</a></h2><p>Blank is not notarized by Apple. See <a href="./install#macos">Install → macOS</a> for how to allow it.</p><h2 id="where-is-my-document-stored" tabindex="-1">Where is my document stored? <a class="header-anchor" href="#where-is-my-document-stored" aria-label="Permalink to &quot;Where is my document stored?&quot;">​</a></h2><p>Files you save are ordinary markdown files wherever you saved them. On top of that, Blank keeps the open document in its own app storage and restores it on the next start, so closing the window doesn&#39;t lose it. This is not a backup, though: <code>Mod</code> <code>N</code> replaces the document with an empty one right away, so save first what you want to keep.</p><h2 id="why-did-blank-change-what-i-typed" tabindex="-1">Why did Blank change what I typed? <a class="header-anchor" href="#why-did-blank-change-what-i-typed" aria-label="Permalink to &quot;Why did Blank change what I typed?&quot;">​</a></h2><p>That&#39;s <a href="./autocorrect">autocorrect</a>. Press <code>Mod</code> <code>Z</code> right away to undo a single correction, or <a href="./configuration#autocorrect">turn a group off</a>.</p><h2 id="the-quotes-look-wrong-for-my-language" tabindex="-1">The quotes look wrong for my language <a class="header-anchor" href="#the-quotes-look-wrong-for-my-language" aria-label="Permalink to &quot;The quotes look wrong for my language&quot;">​</a></h2><p>Quotes follow the language at the bottom right. Press <code>Mod</code> <code>Alt</code> <code>L</code> to <a href="./autocorrect#language">choose yours</a>.</p><h2 id="can-i-use-the-mouse" tabindex="-1">Can I use the mouse? <a class="header-anchor" href="#can-i-use-the-mouse" aria-label="Permalink to &quot;Can I use the mouse?&quot;">​</a></h2><p>You can click to place the cursor, select text, and <code>Mod</code> + Click a link to open it. Everything else is done with the keyboard, on purpose.</p><h2 id="i-found-a-bug-or-have-an-idea" tabindex="-1">I found a bug or have an idea <a class="header-anchor" href="#i-found-a-bug-or-have-an-idea" aria-label="Permalink to &quot;I found a bug or have an idea&quot;">​</a></h2><p>Please <a href="https://github.com/FPurchess/blank/issues/new/choose" target="_blank" rel="noreferrer">open an issue</a> on GitHub.</p>',13)])])}const p=a(r,[["render",s]]);export{m as __pageData,p as default};
